/// <summary>
/// <para>
/// Native-only device features.
/// </para>
/// <para>
/// These extend the standard <c>WGPUFeatureName</c> values and can be passed to
/// <c>WGPUDeviceDescriptor::requiredFeatures</c> to request additional
/// capabilities when creating a device.
/// </para>
/// </summary>
public enum NativeFeature : uint
{
    /// <summary>
    /// <para>
    /// Allows the use of immediate data: small, fast blocks of memory
    /// that can be updated inside a render pass, compute pass, or render
    /// bundle encoder.
    /// </para>
    /// <para>
    /// Enables <see cref="WebGpu.RenderPassEncoderSetImmediates" />,
    /// <see cref="WebGpu.ComputePassEncoderSetImmediates" />,
    /// <see cref="WebGpu.RenderBundleEncoderSetImmediates" />,
    /// non-zero <c>immediateSize</c> in <see cref="PipelineLayout" />,
    /// and non-zero <c>maxImmediateSize</c> in <see cref="Limits" />.
    /// </para>
    /// <para>
    /// A block of immediate data can be declared in WGSL with
    /// <c>var&lt;immediate&gt;:</c>
    /// @code
    /// struct Immediates { example: f32, }
    /// var&lt;immediate&gt; c: Immediates;
    /// @endcode
    /// </para>
    /// <para>
    /// In GLSL, this corresponds to <c>layout</c>(immediates) <c>uniform</c> <c>Name</c> @c {..}.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - DX12
    /// - Vulkan
    /// - Metal
    /// - OpenGL (emulated with uniforms)
    /// - WebGPU
    /// </para>
    /// <para>
    /// This is a web and native feature.
    /// </para>
    /// </summary>
    Immediates = 0x00030001,

    /// <summary>
    /// <para>
    /// Enables device-specific texture format features.
    /// </para>
    /// <para>
    /// By default only texture format properties as defined by the WebGPU
    /// specification are allowed. Enabling this feature flag extends the
    /// features of each format to the ones supported by the current device.
    /// Note that without this flag, read/write storage access is not allowed
    /// at all.
    /// </para>
    /// <para>
    /// This extension does not enable additional formats.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Vulkan
    /// - DX12
    /// - Metal
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    TextureAdapterSpecificFormatFeatures = 0x00030002,

    /// <summary>
    /// <para>
    /// Allows the use of a buffer containing the actual number of draw calls.
    /// </para>
    /// <para>
    /// Enables <see cref="WebGpu.RenderPassEncoderMultiDrawIndirectCount" /> and
    /// <see cref="WebGpu.RenderPassEncoderMultiDrawIndexedIndirectCount" />.
    /// </para>
    /// <para>
    /// This feature being present also implies that all calls to
    /// <see cref="WebGpu.RenderPassEncoderMultiDrawIndirect" /> and
    /// <see cref="WebGpu.RenderPassEncoderMultiDrawIndexedIndirect" /> are not being
    /// emulated with a series of <c>draw_indirect</c> calls.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - DX12
    /// - Vulkan 1.2+ (or VK_KHR_draw_indirect_count)
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    MultiDrawIndirectCount = 0x00030004,

    /// <summary>
    /// <para>
    /// Enables bindings of writable storage buffers and textures visible
    /// to vertex shaders.
    /// </para>
    /// <para>
    /// Note: some (tiled-based) platforms do not support vertex shaders
    /// with any side-effects.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - All
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    VertexWritableStorage = 0x00030005,

    /// <summary>
    /// <para>
    /// Allows the user to create uniform arrays of textures in shaders:
    /// </para>
    /// <para>
    /// - WGSL: <c>var</c> <c>textures:</c> <c>binding_array&lt;texture_2d&lt;f32&gt;,</c> <c>10&gt;</c>
    /// - GLSL: <c>uniform</c> <c>texture2D</c> <c>textures</c>[10]
    /// </para>
    /// <para>
    /// If <see cref="NativeFeature.StorageResourceBindingArray" /> is supported
    /// as well as this, the user may also create uniform arrays of storage
    /// textures.
    /// </para>
    /// <para>
    /// This capability allows them to exist and to be indexed by dynamically
    /// uniform values.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - DX12
    /// - Metal (with MSL 2.0+ on macOS 10.13+)
    /// - Vulkan
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    TextureBindingArray = 0x00030006,

    /// <summary>
    /// <para>
    /// Allows shaders to index sampled texture and storage buffer resource
    /// arrays with dynamically non-uniform values:
    /// </para>
    /// <para>
    /// e.g. <c>texture_array</c>[vertex_data]
    /// </para>
    /// <para>
    /// In order to use this capability, the corresponding GLSL extension must
    /// be enabled:
    /// </para>
    /// <para>
    /// @c \#extension <c>GL_EXT_nonuniform_qualifier</c> <c>:</c> <c>require</c>
    /// </para>
    /// <para>
    /// and then used either as <c>nonuniformEXT</c> qualifier in variable
    /// declaration or as <c>nonuniformEXT</c> constructor.
    /// </para>
    /// <para>
    /// WGSL and HLSL do not need any extension.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - DX12
    /// - Metal (with MSL 2.0+ on macOS 10.13+)
    /// - Vulkan 1.2+ (or VK_EXT_descriptor_indexing)
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    SampledTextureAndStorageBufferArrayNonUniformIndexing = 0x00030007,

    /// <summary>
    /// <para>
    /// Enables use of Pipeline Statistics Queries. These queries report the
    /// count of various operations performed between the start and stop call.
    /// </para>
    /// <para>
    /// Use <see cref="WebGpu.RenderPassEncoderBeginPipelineStatisticsQuery" /> /
    /// <see cref="WebGpu.RenderPassEncoderEndPipelineStatisticsQuery" /> (or the compute
    /// pass equivalents) to start and stop a query.
    /// </para>
    /// <para>
    /// They must be resolved using <c>wgpuCommandEncoderResolveQuerySet</c> into
    /// a buffer. See <see cref="PipelineStatisticName" /> for the list of available
    /// statistics.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Vulkan
    /// - DX12
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    PipelineStatisticsQuery = 0x00030008,

    /// <summary>
    /// <para>
    /// Allows the user to create uniform arrays of storage buffers or
    /// textures in shaders, if <see cref="NativeFeature.BufferBindingArray" />
    /// or <see cref="NativeFeature.TextureBindingArray" /> (respectively)
    /// is also supported.
    /// </para>
    /// <para>
    /// This capability allows them to exist and to be indexed by dynamically
    /// uniform values.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Metal (with MSL 2.2+ on macOS 10.13+)
    /// - Vulkan
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    StorageResourceBindingArray = 0x00030009,

    /// <summary>
    /// <para>
    /// Allows the user to create bind groups containing arrays with fewer
    /// bindings than the <c>WGPUBindGroupLayout</c> requires.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Vulkan
    /// - DX12
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    PartiallyBoundBindingArray = 0x0003000A,

    /// <summary>
    /// <para>
    /// Enables normalized 16-bit texture formats:
    /// <see cref="TextureFormat.R16Unorm" />, <see cref="TextureFormat.R16Snorm" />,
    /// <see cref="TextureFormat.RG16Unorm" />, <see cref="TextureFormat.RG16Snorm" />,
    /// <see cref="TextureFormat.RGBA16Unorm" />, <see cref="TextureFormat.RGBA16Snorm" />.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Vulkan
    /// - DX12
    /// - Metal
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    TextureFormat16bitNorm = 0x0003000B,

    /// <summary>
    /// <para>
    /// Enables ASTC HDR family of compressed textures.
    /// </para>
    /// <para>
    /// Compressed textures sacrifice some quality in exchange for
    /// significantly reduced bandwidth usage.
    /// </para>
    /// <para>
    /// Support for this feature guarantees availability of
    /// <c>COPY_SRC</c> | <c>COPY_DST</c> | <c>TEXTURE_BINDING</c> for ASTC formats
    /// with the HDR channel type.
    /// <see cref="NativeFeature.TextureAdapterSpecificFormatFeatures" /> may
    /// enable additional usages.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Metal
    /// - Vulkan
    /// - OpenGL
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    TextureCompressionAstcHdr = 0x0003000C,

    /// <summary>
    /// <para>
    /// Removes the WebGPU restriction that <c>MAP_READ</c> and <c>MAP_WRITE</c>
    /// buffer usages must be paired exclusively with <c>COPY_DST</c> and
    /// <c>COPY_SRC</c> respectively.
    /// </para>
    /// <para>
    /// This is only beneficial on systems that share memory between CPU and
    /// GPU. If enabled on a system that doesn't, this can severely hinder
    /// performance. Only use if you understand the consequences.
    /// </para>
    /// <para>
    /// Supported platforms:
    /// - Vulkan
    /// - DX12
    /// - Metal
    /// </para>
    /// <para>
    /// This is a native only feature.
    /// </para>
    /// </summary>
    MappablePrimaryBuffers = 0x0003000E,

    /// <summary>
    /// <para>
    /// Allows the user to create arrays of buffers in shaders:
    /// </para>
    /// <para>
