/// <summary>
/// The status enum for <see cref="WebGpu.SurfaceGetCurrentTexture" />.
/// </summary>
public enum SurfaceGetCurrentTextureStatus : uint
{
    /// <summary>
    /// Yay! Everything is good and we can render this frame.
    /// </summary>
    SuccessOptimal = 0x00000001,

    /// <summary>
    /// Still OK - the surface can present the frame, but in a suboptimal way. The surface may need reconfiguration.
    /// </summary>
    SuccessSuboptimal = 0x00000002,

    /// <summary>
    /// Some operation timed out while trying to acquire the frame.
    /// </summary>
    Timeout = 0x00000003,

    /// <summary>
    /// The surface is too different to be used, compared to when it was originally created.
    /// </summary>
    Outdated = 0x00000004,

    /// <summary>
    /// The connection to whatever owns the surface was lost, or generally needs to be fully reinitialized.
    /// </summary>
    Lost = 0x00000005,

    /// <summary>
    /// There was some deterministic error (for example, the surface is not configured, or there was an OutStructChainError). Should produce ImplementationDefinedLogging containing details.
    /// </summary>
    Error = 0x00000006,

    /// <summary>
    /// <para>
    /// The surface texture was not acquired because the window is occluded
    /// (e.g. minimized or fully covered by another window).
    /// </para>
    /// <para>
    /// No texture is returned and the <c>texture</c> field of
    /// <c>WGPUSurfaceTexture</c> will be NULL. The surface and swapchain remain
    /// valid -- there is no need to reconfigure or recreate the surface.
    /// </para>
    /// <para>
    /// Applications should skip rendering for the current frame and try
    /// again once the window is no longer occluded. If you are using a
    /// windowing library such as winit, listen for the window's "occluded"
    /// event and request a new redraw when the window becomes visible again.
    /// </para>
    /// <para>
    /// When does this occur?
    /// </para>
    /// <para>
    /// Currently this status is only produced by the Metal backend on macOS.
    /// When a window is not visible (checked via the <c>NSWindow</c>
    /// <c>occlusionState</c> property), acquiring the next drawable would block
    /// for up to one second waiting for vsync. wgpu-native returns
    /// <c>Occluded</c> instead to avoid that hang.
    /// </para>
    /// <para>
    /// Other backends (Vulkan, DX12, GL) do not currently report this
    /// status; an occluded window on those backends may produce
    /// <c>WGPUSurfaceGetCurrentTextureStatus_Timeout</c> or simply succeed
    /// normally.
    /// </para>
    /// </summary>
    Occluded = 0x00030001,
}

