/// <summary>
/// Status returned from a call to ::wgpuInstanceWaitAny.
/// </summary>
public enum WaitStatus : uint
{
    /// <summary>
    /// At least one WGPUFuture completed successfully.
    /// </summary>
    Success = 0x00000001,

    /// <summary>
    /// The wait operation succeeded, but no WGPUFutures completed within the timeout.
    /// </summary>
    TimedOut = 0x00000002,

    /// <summary>
    /// The call was invalid for some reason (see Wait Any).
    /// Should produce ImplementationDefinedLogging containing details.
    /// </summary>
    Error = 0x00000003,
}
